        t = cls()
        t.t_us = _rt.get(data, '<I', 0)
        t.count = _rt.get(data, '<B', 4)
        t.avg = [_rt.get_fixed(data, '<H', 5 + i * 2, 1e-06, 65535) for i in range(8)]
        t.max = [_rt.get_fixed(data, '<H', 21 + i * 2, 1e-06, 65535) for i in range(8)]
        return t

